inline void draw(TFT_eSPI& tft) {
    static uint16_t line[WIDTH];  // 640 bytes SRAM
    tft.startWrite();
    for (uint16_t y = 0; y < HEIGHT; ++y) {
        const size_t base = static_cast<size_t>(y) * WIDTH;
        for (uint16_t x = 0; x < WIDTH; ++x) {
            const uint16_t rgb565 = pgm_read_word(&pixels[base + x]);
            // TFT_eSPI pushImage() uses wire-order bytes by default.
            // Convert standard RGB565 words without changing the display's
            // global swap setting (other visualization colors stay intact).
            line[x] = static_cast<uint16_t>((rgb565 << 8) | (rgb565 >> 8));
        }
        tft.pushImage(0, y, WIDTH, 1, line);
    }
    tft.endWrite();
}

inline void show(TFT_eSPI& tft) {
    draw(tft);
    delay(HOLD_MS);
}
